public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.round(n * 0.05);
    int[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);
    double sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (n - 2 * k);
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }
    int[] pairs = new int[arr.length / 2];
    for (int i = 0; i < arr.length; i += 2) {
        pairs[i / 2] = arr[i] + arr[i + 1];
    }
    for (int i = 0; i < pairs.length; i++) {
        if (pairs[i] % k != 0) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a priority queue to store the nodes to visit
    PriorityQueue<Node> queue = new PriorityQueue<>();

    // Add node 0 to the queue with a priority of 0
    queue.add(new Node(0, 0));

    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    while (!queue.isEmpty()) {
        // Get the node with the highest priority from the queue
        Node current = queue.poll();

        // If the current node has not been visited before, mark it as visited and add its neighbors to the queue
        if (!visited[current.node]) {
            visited[current.node] = true;
            for (int neighbor : graph.neighbors(current.node)) {
                if (!visited[neighbor]) {
                    queue.add(new Node(neighbor, current.priority + 1));
                }
            }
        }

        // If the current node has an apple, update the minimum time required to collect all apples and return to node 0
        if (hasApple[current.node]) {
            minTime = Math.max(minTime, current.priority + 1);
        }
    }

    return minTime;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    while (result.length() < chars.length) {
        int minIndex = 0;
        int maxIndex = chars.length - 1;
        while (minIndex < maxIndex) {
            result.append(chars[minIndex]);
            minIndex++;
        }
        while (maxIndex >= 0) {
            result.append(chars[maxIndex]);
            maxIndex--;
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;
    int leftSum = 0;
    for (int i = 0; i < nums.length; i++) {
        leftSum += nums[i];
        if (leftSum == average) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    String[] morseCodes = {".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---", "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."};
    Set<String> seen = new HashSet<>();
    for (String word : words) {
        StringBuilder code = new StringBuilder();
        for (char c : word.toCharArray()) {
            code.append(morseCodes[c - 'a']);
        }
        seen.add(code.toString());
    }
    return seen.size();
}

