        }
    }
    return maxSum;
}

public int findMinFibonacciNumbers(int k) {
    int[] fibonacciNumbers = { 1, 1 };
    int i = 2;
    while (fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2] <= k) {
        fibonacciNumbers[i] = fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2];
        i++;
    }
    int count = 0;
    while (k > 0) {
        for (int j = i - 1; j >= 0; j--) {
            if (fibonacciNumbers[j] <= k) {
                k -= fibonacciNumbers[j];
                count++;
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }
    return -1;
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (Character.isLowerCase(c) && i + 1 < s.length() && Character.isUpperCase(s.charAt(i + 1))) {
            continue;
        }
        if (Character.isUpperCase(c) && i + 1 < s.length() && Character.isLowerCase(s.charAt(i + 1))) {
            continue;
        }
        sb.append(c);
    }
    return sb.toString();
}

