public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    while (n > 0) {
        int charValue = (k - 1) % 26 + 1;
        sb.append((char) ('a' + charValue - 1));
        k = (k - charValue) / 26;
        n--;
    }
    return sb.toString();
}

