public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    return (x1 - x2) * (y3 - y2) - (y1 - y2) * (x3 - x2) != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int factor2 = 2, factor3 = 3, factor5 = 5;
    for (int i = 1; i < n; i++) {
        int min = Math.min(factor2, Math.min(factor3, factor5));
        uglyNumbers[i] = min;
        if (min == factor2) {
            i2++;
            factor2 = uglyNumbers[i2] * 2;
        }
        if (min == factor3) {
            i3++;
            factor3 = uglyNumbers[i3] * 3;
        }
        if (min == factor5) {
            i5++;
            factor5 = uglyNumbers[i5] * 5;
        }
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int currentLength = 0;
    char currentChar = s.charAt(0);
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            if (currentLength > energy) {
                energy = currentLength;
            }
            currentLength = 1;
            currentChar = s.charAt(i);
        }
    }
    if (currentLength > energy) {
        energy = currentLength;
    }
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result, new Comparator<Integer>() {
        @Override
        public int compare(Integer o1, Integer o2) {
            return o1.toString().compareTo(o2.toString());
        }
    });
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (uniqueNums.add(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

